// ---------------------------------------------------------------------
// (4.2.6) MEDIDAS PELA PARTE VISÍVEL, NÃO PELO IFRAME. No Canva o iframe pode ser bem mais alto que a
// parte que aparece na tela (barras do navegador, rolagem da página). Os "@media (max-height...)" medem
// o iframe INTEIRO, então no Opera/Chrome do celular o menu ficava no tamanho de tela grande e cortava
// embaixo. Aqui o #raizJogo (que já é encaixado só na parte visível) vira um "container" e uma cópia de
// cada @media de altura é escrita como @container (mede o #raizJogo). As cópias vão por último e valem
// por cima. Sem suporte a container queries, nada muda (continuam os @media de antes).
// ---------------------------------------------------------------------
(function espelharMediaEmContainer() {
  try {
    if (!(window.CSS && CSS.supports && CSS.supports('container-type: size'))) return;
    let saida = '';
    for (const el of Array.from(document.querySelectorAll('style'))) {
      if (el.dataset.espelho) continue;
      const t = el.textContent || '';
      let i = 0;
      while ((i = t.indexOf('@media', i)) >= 0) {
        const ab = t.indexOf('{', i);
        if (ab < 0) break;
        let n = 1, j = ab + 1;
        while (j < t.length && n > 0) { const c = t[j++]; if (c === '{') n++; else if (c === '}') n--; }
        const consulta = t.slice(i + 6, ab);
        if (/max-height/.test(consulta) && !/hover|reduced|prefers/.test(consulta)) {
          const nova = consulta.replace(/orientation:\s*landscape/g, 'min-aspect-ratio: 1/1');
          saida += '@container' + nova + t.slice(ab, j) + '\n';
        }
        i = j;
      }
    }
    if (!saida) return;
    raizJogo.style.containerType = 'size';
    const st = document.createElement('style');
    st.dataset.espelho = '1'; st.textContent = saida;
    document.head.appendChild(st);
  } catch (e) { /* segue com os @media normais */ }
})();

// ---------------------------------------------------------------------
// API PARA O MODO HISTÓRIA (e para testes no console do navegador)
//   FutebolJS.novaPartida({ times: ['azulao', 'leoes'], campo: 'varzea', clima: 'chuva', ... })
//   FutebolJS.cadastrarTime({ id: 'meuTime', nome: ..., uniforme: {...}, ... })
//   FutebolJS.salvarTecnico({ nome: 'Fulano', aparencia: { pele, cabelo, estilo, roupa } })
//   FutebolJS.trocarTatica(0, 'retranca')
// ---------------------------------------------------------------------
window.FutebolJS = {
  versao: '4.8.2',
  personagem: PERSONAGEM,                       // (4.3.0) personagem do modo história (nome, número, aparência, pé, comemoração, voz)
  novaPartida(cfg) { montarPartida(cfg); resetMatch(); return PARTIDA; },
  // Saves (tela CARREGAR do menu): salvarJogo(1..3, { nome, resumo, partida }), listarSaves(), apagarSave(n).
  salvarJogo, listarSaves, apagarSave,
  slotHistoria: () => SLOT_HISTORIA,            // (4.7.3) espaço escolhido para o personagem da história (0 = nenhum)
  partida: () => PARTIDA,
  // (4.5.0) história salva por fase + fases em arquivos separados (veja Fases / HistoriaSave)
  historia: { ler: HistoriaSave.ler, gravar: HistoriaSave.gravar, tudo: HistoriaSave.tudo, limpar: HistoriaSave.limpar },
  registrarFase: Fases.registrar, carregarFase: Fases.carregar, executarFase: Fases.executar,
  cadastrarTime(t) { TIMES[t.id] = t; return t; },
  salvarTecnico(t) { salvo.gravar('futebolJs.tecnico.v1', t); return t; },
  trocarTatica: (team, chave) => { if (team === 0) G.taticaManual = true; trocarTatica(team, chave); },
  elencoDoTime: (id) => elencoDoTime(TIMES[id]),
  TIMES, CAMPOS, FORMACOES, TATICAS, DIFICULDADES, CLIMAS, HORARIOS, NOMES, DURACOES,
};

montarPartida(Object.assign({}, PARTIDA_PADRAO, lerTelaDeConfig()));
kickoff(0);
G.state = 'menu';
snapCamera();
drawRadar();
requestAnimationFrame(frame);
try { document.documentElement.lang = ({ pt: 'pt-BR', en: 'en', es: 'es', it: 'it', fr: 'fr' })[Idioma.atual]; } catch (e) { /* ok */ }
if (IDIOMA_PERGUNTAR_SEMPRE || !salvo.ler('futebolJs.idioma.v1', {}).id) telaIdioma();          // (4.3.0) primeira tela: escolher o idioma
